// Check the shared wire fixtures generated by scripts/build-built.sh.
import "./safety"
import { expect, test } from "bun:test"
import { readFileSync } from "node:fs"
import { wireVectors } from "./fixtures/wire-vectors"

const vectors = new URL("../../protocol/vectors/wire.json", import.meta.url)

test("peer mail, signed documents and canonical digests match shared wire vectors", async () => {
  const output = await wireVectors()
  expect(output.digests[output.documents.length].sha256).toBe(output.digests[output.documents.length + 1].sha256)
  expect(JSON.parse(JSON.stringify(output))).toEqual(JSON.parse(readFileSync(vectors, "utf8")))
})
